{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": None}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (7, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_skips_comments_and_trims_fields():
    lines = ["", "  # header", " a , -1 , 1 ", " \t", "b, 0, 0", " c ,1,  \n"]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": -1, "flagged": True},
        {"id": "b", "day": 0, "flagged": False},
        {"id": "c", "day": 1, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not_int,1"])
def test_parse_error_uses_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log([" # comment", "ok,1,1", "  ", bad_line])


def test_dedupe_keeps_last_record_even_when_its_day_is_earlier():
    events = parse_transcript_log(["c,3,1", "b,9,1", "b,2,0", "z,1,1", "a,2,1"])
    assert dedupe_transcripts(events) == [events[3], events[4], events[2], events[0]]


def test_daily_flag_counts_inclusive_zero_filled_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,", "e,4,0", "f,5,1", "g,6,1"])
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["a,2,1", "b,7,1"]), "b": parse_transcript_log(["c,8,0"]), "c": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"a": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": None}], "b": [{"flagged": True}], "a": [{"flagged": True}], "empty": []}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 10) == ["a", "b", "z"]


def test_flag_rate_by_group_includes_empty_in_sorted_order():
    groups = {"c": [], "b": [{"flagged": None}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("c", None)]


@pytest.mark.parametrize("counts, expected", [([], 0), ([-1, 0], 0), ([1, 2, 0, 1, -2, 1], 2)])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
